package com.marketplace.productservice;
import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.*;
@RestControllerAdvice class ApiExceptionHandler{@ExceptionHandler(InsufficientStockException.class)ResponseEntity<ErrorResponse> stock(InsufficientStockException e){return error(HttpStatus.CONFLICT,e.getMessage());}@ExceptionHandler({IllegalArgumentException.class,NoSuchElementException.class})ResponseEntity<ErrorResponse> notFound(RuntimeException e){return error(HttpStatus.NOT_FOUND,e.getMessage());}@ExceptionHandler(MethodArgumentNotValidException.class)ResponseEntity<ErrorResponse> invalid(MethodArgumentNotValidException e){return error(HttpStatus.BAD_REQUEST,"Dados inválidos");}private ResponseEntity<ErrorResponse> error(HttpStatus s,String m){return ResponseEntity.status(s).body(new ErrorResponse(Instant.now(),s.value(),m));}record ErrorResponse(Instant timestamp,int status,String message){}}
